package migrations

import (
	"encoding/json"
	"regexp"
	"strings"
	"testing"
	"time"

	"github.com/IWillBeGoogler/iwillbegoogler-monolith-go/internal/domain/diagram"
)

const templateSeed = "00057_diagram_template_seed.sql"

var seedDoc = regexp.MustCompile(`(?s)\$tpl\$(.*?)\$tpl\$::jsonb`)

// The seed is generated by the editor (Web/editor/src/templates/seedSql.ts);
// every document in it must pass the same validation as a saved file, or a
// forked template would be rejected on its first save.
func TestTemplateSeedDocumentsAreValid(t *testing.T) {
	raw, err := FS.ReadFile(templateSeed)
	if err != nil {
		t.Fatal(err)
	}
	sql := string(raw)
	docs := seedDoc.FindAllStringSubmatch(sql, -1)
	if want := strings.Count(sql, "INSERT INTO dg_templates"); len(docs) != want || want == 0 {
		t.Fatalf("%d documents for %d templates", len(docs), want)
	}
	now := time.Now()
	for i, m := range docs {
		var head struct {
			ID   string `json:"id"`
			Name string `json:"name"`
		}
		if err := json.Unmarshal([]byte(m[1]), &head); err != nil {
			t.Fatalf("document %d: %v", i, err)
		}
		if _, err := diagram.Prepare(json.RawMessage(m[1]), head.ID, head.Name, now, now); err != nil {
			t.Errorf("%s (%s): %v", head.Name, head.ID, err)
		}
	}
}
